WN.lb(16,{"mt_vKcxX6iNOA":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"What is the numerator of 5/9?","choices":["5","9","14"],"answer":0,"hint":"The numerator is the top number.","explain":"The numerator is 5."},{"type":"mc","id":"m2","prompt":"What does the denominator tell you?","choices":["How many equal parts the whole is split into","How many parts you have","How big the whole is"],"answer":0,"hint":"Think of the bottom number in 3/4.","explain":"The denominator gives the number of equal parts in the whole."},{"type":"mc","id":"m3","prompt":"Which fraction is in simplest form?","choices":["3/7","2/4","6/9"],"answer":0,"hint":"Can the top and bottom both be divided by the same number (other than 1)?","explain":"2/4 simplifies to 1/2 and 6/9 to 2/3, but 3/7 can't be simplified."},{"type":"mc","id":"m4","prompt":"In {n}/{d}, which number is the denominator?","choices":["{d}","{n}","{=n+d}"],"answer":0,"hint":"The denominator is on the bottom.","explain":"The denominator is {d}: the whole is cut into {d} equal parts.","params":{"n":[1,8],"d":[2,9]},"where":"n<d"},{"type":"mc","id":"m5","prompt":"A cake is cut into {d} equal slices and you eat {n}. What fraction of the cake did you eat?","choices":["{n}/{d}","{d}/{n}","{n}/{=n+d}"],"answer":0,"hint":"The bottom number is the number of equal slices in the whole cake.","explain":"{n} of {d} equal slices is {n}/{d}.","params":{"n":[1,8],"d":[2,9]},"where":"n<d"},{"type":"mc","id":"m6","prompt":"Which is a proper fraction?","choices":["3/5","5/3","4/4"],"answer":0,"hint":"In a proper fraction the numerator is smaller than the denominator.","explain":"3/5 is less than one whole; 5/3 and 4/4 are improper."},{"type":"mc","id":"m7","prompt":"What is a mixed number?","choices":["A whole number and a fraction together, like 1¾","A fraction with 1 on top","Two fractions added together"],"answer":0,"hint":"Think of '1 and three quarters'.","explain":"A mixed number combines a whole number and a fraction, such as 1¾."}]},"practice":[{"type":"mc","id":"p1","prompt":"In 2/5, which number is the denominator?","choices":["5","2","7"],"answer":0,"hint":"The denominator is the bottom number.","explain":"The denominator is 5: the whole is cut into 5 equal parts."},{"type":"mc","id":"p2","prompt":"Which is a unit fraction?","choices":["1/6","2/6","6/1"],"answer":0,"hint":"A unit fraction has 1 on top.","explain":"1/6 has numerator 1, so it is a unit fraction."},{"type":"mc","id":"p3","prompt":"Which is an improper fraction?","choices":["7/4","3/4","1/2"],"answer":0,"hint":"Look for a top number at least as big as the bottom number.","explain":"7/4 has a numerator bigger than its denominator, so it is improper (it is more than 1 whole)."},{"type":"mc","id":"p4","prompt":"A pizza is cut into {d} equal slices and you eat {n}. What fraction did you eat?","choices":["{n}/{d}","{d}/{n}","{n}/{=d-n}"],"answer":0,"hint":"The whole is {d} slices.","explain":"{n} of {d} equal slices is {n}/{d}.","params":{"n":[1,5],"d":[3,8]},"where":"n<d"},{"type":"mc","id":"p5","prompt":"In {n}/{d}, which number is the numerator?","choices":["{n}","{d}","{=n+d}"],"answer":0,"hint":"The numerator is the top number.","explain":"The numerator is {n}: it counts how many parts we mean.","params":{"n":[1,7],"d":[2,9]},"where":"n<d"}],"explain":{"kid":["A fraction like 3/4 has two numbers. The bottom number is the denominator. It tells you how many equal parts the whole is cut into. The top number is the numerator. It tells you how many of those parts we mean.","So 3/4 means: cut it into 4 equal parts and take 3. A fraction with 1 on top, like 1/4, is called a unit fraction."],"adult":["The numerator counts the parts. The denominator says how many equal parts make the whole. A unit fraction has 1 on top. A proper fraction is less than 1, like 3/4. An improper fraction has a top number equal to or bigger than the bottom, like 7/4. A mixed number, like 1¾, is a whole number and a fraction.","Equivalent fractions have the same value, like 1/2 and 2/4. A fraction is in simplest form when no number except 1 divides both the top and the bottom, as in 3/7 (but not 6/9)."]},"familyTip":"When cutting a sandwich or pizza, name it: 'four equal pieces, so each is one quarter, 1/4'.","keyIdea":"The denominator says how many equal parts the whole has; the numerator says how many of them you mean.","visual":{"type":"fracbar","caption":"Split the bar into equal parts and shade some. The fraction updates as you go.","opts":{"d":4,"shade":1}}},"mt_cFltwUQi-d":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"What is 1/4 of 20?","answer":5,"hint":"Split 20 into 4 equal groups.","explain":"20 ÷ 4 = 5."},{"type":"numeric","id":"m2","prompt":"What is 2/4 of 8?","answer":4,"hint":"1/4 of 8 is 2.","explain":"2 × 2 = 4 (the same as 1/2 of 8)."},{"type":"numeric","id":"m3","prompt":"A ribbon is 12 cm long. How many cm is 3/4 of it?","answer":9,"hint":"1/4 of 12 cm is 3 cm.","explain":"3 × 3 = 9 cm."},{"type":"numeric","id":"m4","prompt":"What is 1/{d} of {=d*k}?","answer":"k","hint":"Split {=d*k} into {d} equal groups.","explain":"{=d*k} ÷ {d} = {k}.","params":{"d":[2,6],"k":[2,6]}},{"type":"numeric","id":"m5","prompt":"What is {n}/{d} of {=d*k}?","answer":"n*k","hint":"Find 1/{d} first.","explain":"1/{d} of {=d*k} is {k}, so {n}/{d} is {n} × {k} = {=n*k}.","params":{"d":[3,6],"n":[2,5],"k":[2,5]},"where":"n<d"},{"type":"numeric","id":"m6","prompt":"A ribbon is {=d*k} cm long. How many cm is 1/{d} of it?","answer":"k","hint":"Divide the length by {d}.","explain":"{=d*k} ÷ {d} = {k} cm.","params":{"d":[2,5],"k":[2,6]}},{"type":"mc","id":"m7","prompt":"How do you find 1/5 of 20?","choices":["Divide 20 by 5","Multiply 20 by 5","Subtract 5 from 20"],"answer":0,"hint":"1/5 means one of 5 equal parts.","explain":"20 ÷ 5 = 4, so 1/5 of 20 is 4."}]},"practice":[{"type":"numeric","id":"p1","prompt":"Find 1/{d} of {=d*k}.","answer":"k","hint":"Split {=d*k} into {d} equal groups.","explain":"{=d*k} ÷ {d} = {k}.","params":{"d":[2,5],"k":[2,5]}},{"type":"numeric","id":"p2","prompt":"What is 1/3 of 9?","answer":3,"hint":"Split 9 into 3 equal groups.","explain":"9 ÷ 3 = 3."},{"type":"numeric","id":"p3","prompt":"What is 3/4 of 8?","answer":6,"hint":"First find 1/4 of 8, then take 3 of them.","explain":"1/4 of 8 is 2, so 3/4 is 3 × 2 = 6."},{"type":"mc","id":"p4","prompt":"A rectangle is cut into 4 pieces of different sizes. Does that show quarters?","choices":["No, quarters must be 4 equal parts","Yes, there are 4 pieces","Yes, if you count the biggest piece"],"answer":0,"hint":"What does a fraction need its parts to be?","explain":"Quarters are 4 equal parts. Four pieces of different sizes don't show quarters."},{"type":"numeric","id":"p5","prompt":"Find {n}/{d} of {=d*k}.","answer":"n*k","hint":"First find 1/{d} of {=d*k}.","explain":"1/{d} of {=d*k} is {k}, so {n}/{d} is {n} × {k} = {=n*k}.","params":{"d":[3,5],"n":[2,4],"k":[2,4]},"where":"n<d"}],"explain":{"kid":["To find a fraction of an amount, share it into equal groups. For 1/4 of 12, split 12 into 4 equal groups. There are 3 in each, so 1/4 of 12 is 3.","For 3/4 of 12, take 3 of those groups: 3 + 3 + 3 = 9."],"adult":["Divide by the denominator to find one part, then multiply by the numerator: 3/4 of 12 = (12 ÷ 4) × 3 = 9.","The same works for lengths and shapes, as long as the parts are equal in size. A shape cut into 4 unequal pieces does not show quarters."]},"familyTip":"Ask for a fraction of a handful: 'Can you give me a quarter of these 12 raisins?' Check by counting the groups.","keyIdea":"To find a fraction of an amount, split it into equal groups, then take some of the groups.","visual":{"type":"share","caption":"Share 12 into 4 equal groups. One group is a quarter of 12.","opts":{"total":12,"groups":4,"show":1}}},"mt_MyGblah2yY":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"1/3 of 6 = ?","answer":2,"hint":"Split 6 into 3 equal groups.","explain":"6 ÷ 3 = 2."},{"type":"mc","id":"m2","prompt":"True or false: 2/4 of 10 = 1/2 of 10","choices":["True","False"],"answer":0,"hint":"Is 2/4 the same amount as 1/2?","explain":"Both equal 5, because 2/4 and 1/2 are the same amount."},{"type":"numeric","id":"m3","prompt":"1/2 of 14 = ?","answer":7,"hint":"Split 14 into 2 equal groups.","explain":"14 ÷ 2 = 7."},{"type":"numeric","id":"m4","prompt":"1/2 of {=2*k} = ?","answer":"k","hint":"Split {=2*k} into 2 equal groups.","explain":"{=2*k} ÷ 2 = {k}.","params":{"k":[2,9]}},{"type":"numeric","id":"m5","prompt":"2/4 of {=4*k} = ?","answer":"2*k","hint":"1/4 of {=4*k} is {k}.","explain":"2 × {k} = {=2*k}, the same as 1/2 of {=4*k}.","params":{"k":[2,6]}},{"type":"mc","id":"m6","prompt":"True or false: 2/4 of {=4*k} = 1/2 of {=4*k}","choices":["True","False"],"answer":0,"hint":"Are 2/4 and 1/2 the same amount?","explain":"Both are {=2*k}, because 2/4 = 1/2.","params":{"k":[2,5]}},{"type":"mc","id":"m7","prompt":"Which is the same amount as 2/4?","choices":["1/2","1/4","2/2"],"answer":0,"hint":"Picture 2 quarters of a pizza.","explain":"Two quarters make one half."}]},"practice":[{"type":"numeric","id":"p1","prompt":"What is half of {=2*k}? (That's 1/2 of {=2*k}.)","answer":"k","hint":"Split {=2*k} into 2 equal groups.","explain":"{=2*k} ÷ 2 = {k}.","params":{"k":[3,9]}},{"type":"mc","id":"p2","prompt":"Which is the same amount as 1/2?","choices":["2/4","1/4","2/3"],"answer":0,"hint":"Picture a cake cut into 4 equal pieces.","explain":"Two quarters make a half, so 2/4 = 1/2."},{"type":"numeric","id":"p3","prompt":"2/4 of 8 = ?","answer":4,"hint":"1/4 of 8 is 2.","explain":"2 × 2 = 4, which is the same as 1/2 of 8."},{"type":"mc","id":"p4","prompt":"How do you write 'a quarter of 12 is 3'?","choices":["1/4 of 12 = 3","4/1 of 12 = 3","1/4 + 12 = 3"],"answer":0,"hint":"A quarter is 1/4, and 'is' becomes =.","explain":"1/4 of 12 = 3."},{"type":"numeric","id":"p5","prompt":"1/3 of {=3*k} = ?","answer":"k","hint":"Split {=3*k} into 3 equal groups.","explain":"{=3*k} ÷ 3 = {k}.","params":{"k":[2,5]}}],"explain":{"kid":["We can write fraction facts as number sentences: 1/2 of 6 = 3.","Different fractions can be the same amount. Cut a cake into 4 equal pieces and take 2: that's the same as half the cake. So 2/4 = 1/2."],"adult":["Writing 'fraction of' sentences connects fractions to division: 1/2 of 6 is 6 ÷ 2.","Recognising 2/4 = 1/2 is the first taste of equivalence. The whole is cut into twice as many parts and twice as many are taken, so the amount stays the same."]},"familyTip":"Fold a sheet of paper in half, then in half again, and shade 2 of the 4 parts. Is it still half?","keyIdea":"We can write fraction facts like 1/2 of 6 = 3, and different fractions can name the same amount.","visual":{"type":"fracbar","caption":"Shade parts of the whole. Switch between a bar and a pie.","opts":{"d":3,"shade":1,"pie":true}}},"mt_Kr3IyA6m-O":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"0 to 1 is split into 5 equal jumps. Which fraction is at the mark after 2 jumps?","choices":["2/5","1/2","5/2"],"answer":0,"hint":"Count the jumps from 0 out of the total.","explain":"2 jumps out of 5 is 2/5."},{"type":"mc","id":"m2","prompt":"Where is 4/4 on the number line?","choices":["At 1","Between 0 and 1","At 4"],"answer":0,"hint":"4 jumps out of 4.","explain":"4/4 is one whole, so it sits at 1."},{"type":"order","id":"m3","prompt":"Put these numbers in order on the number line, smallest first.","items":["0","1/3","2/3","1"],"hint":"Thirds: split 0 to 1 into 3 equal jumps.","explain":"0 < 1/3 < 2/3 < 1."},{"type":"mc","id":"m4","prompt":"0 to 1 is split into {d} equal jumps. Which fraction is at the mark after {n} jumps?","choices":["{n}/{d}","{d}/{n}","1/{=n+d}"],"answer":0,"hint":"Count the jumps from 0, out of the total number of jumps.","explain":"{n} jumps out of {d} is {n}/{d}.","params":{"n":[1,7],"d":[3,8]},"where":"n<d"},{"type":"mc","id":"m5","prompt":"Which is bigger, 1/{a} or 1/{b}?","choices":["1/{a}","1/{b}","They are equal"],"answer":0,"hint":"Fewer equal parts means bigger parts.","explain":"Splitting into {a} gives bigger parts than splitting into {b}, so 1/{a} is bigger.","params":{"a":[2,9],"b":[2,9]},"where":"a<b"},{"type":"order","id":"m6","prompt":"Put these fifths in order, smallest first.","items":["1/5","2/5","4/5","6/5"],"hint":"They all have the same denominator, so compare the numerators.","explain":"1/5 < 2/5 < 4/5 < 6/5 (and 6/5 is past 1)."},{"type":"mc","id":"m7","prompt":"Where does 5/4 go on the number line?","choices":["Just past 1","Between 0 and 1","At 5"],"answer":0,"hint":"4/4 is at 1.","explain":"5/4 is one more quarter after 4/4 = 1."}]},"practice":[{"type":"mc","id":"p1","prompt":"0 to 1 is split into {d} equal jumps. What is the first mark?","choices":["1/{d}","{d}","1/{=d+1}"],"answer":0,"hint":"Each jump is one of {d} equal parts.","explain":"One jump out of {d} equal jumps is 1/{d}.","params":{"d":[3,8]}},{"type":"mc","id":"p2","prompt":"Where does 3/4 go?","choices":["Three of four equal jumps from 0","Between 0 and 1/4","Past 1"],"answer":0,"hint":"The denominator gives the number of jumps between 0 and 1.","explain":"Split 0 to 1 into 4 equal jumps and count 3 of them."},{"type":"mc","id":"p3","prompt":"Which is bigger, 1/3 or 1/4?","choices":["1/3","1/4","They are equal"],"answer":0,"hint":"Is a third of a cake bigger or smaller than a quarter?","explain":"Splitting into 3 gives bigger parts than splitting into 4, so 1/3 > 1/4."},{"type":"order","id":"p4","prompt":"Put these in order, smallest first.","items":["1/4","1/2","3/4","1"],"hint":"Think of quarters on the line: 1/2 is the same as 2/4.","explain":"1/4 < 2/4 (= 1/2) < 3/4 < 4/4 (= 1)."},{"type":"mc","id":"p5","prompt":"Which is smaller, 1/{a} or 1/{b}?","choices":["1/{b}","1/{a}","They are equal"],"answer":0,"hint":"More equal parts means smaller parts.","explain":"Splitting into {b} gives smaller parts than splitting into {a}, so 1/{b} is smaller.","params":{"a":[2,9],"b":[2,9]},"where":"a<b"}],"explain":{"kid":["Fractions are numbers, so they have a place on the number line. Split the gap from 0 to 1 into equal jumps.","With 4 equal jumps, the marks are 1/4, 2/4 and 3/4, and 4/4 is at 1."],"adult":["Seeing fractions as points on a line, not only as slices of shapes, matters for later work with decimals, measures and algebra. To place n/d, split 0 to 1 into d equal intervals and count n of them from 0.","Fractions bigger than 1, like 5/4, carry on past 1. A bigger denominator means smaller jumps, so 1/4 is less than 1/3."]},"familyTip":"Draw a line from 0 to 1 on a strip of paper, fold it into equal parts and label the creases.","keyIdea":"Fractions are numbers with their own place on the number line.","visual":{"type":"numline","caption":"Drag the point along the number line. It snaps to each equal step.","opts":{"d":4,"max":1,"start":3}}},"mt_FbDKeLfBCo":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"3/4 = ?/8. What is the missing numerator?","answer":6,"hint":"4 × 2 = 8.","explain":"Multiply the top by 2 as well: 3 × 2 = 6."},{"type":"mc","id":"m2","prompt":"Which fraction equals 2/5?","choices":["4/10","3/6","2/10"],"answer":0,"hint":"Multiply top and bottom by the same number.","explain":"2/5 = (2 × 2)/(5 × 2) = 4/10."},{"type":"numeric","id":"m3","prompt":"6/9 = 2/?. What is the missing denominator?","answer":3,"hint":"6 ÷ 3 = 2.","explain":"Divide the bottom by 3 as well: 9 ÷ 3 = 3."},{"type":"numeric","id":"m4","prompt":"{n}/{d} = ?/{=d*k}. What is the missing numerator?","answer":"n*k","hint":"What was the denominator multiplied by?","explain":"{d} × {k} = {=d*k}, so the numerator is {n} × {k} = {=n*k}.","params":{"n":[1,4],"d":[2,5],"k":[2,5]},"where":"n<d"},{"type":"numeric","id":"m5","prompt":"{n}/{d} = {=n*k}/?. What is the missing denominator?","answer":"d*k","hint":"What was the numerator multiplied by?","explain":"{n} × {k} = {=n*k}, so the denominator is {d} × {k} = {=d*k}.","params":{"n":[1,4],"d":[2,5],"k":[2,5]},"where":"n<d"},{"type":"mc","id":"m6","prompt":"Which fraction equals {n}/{d}?","choices":["{=n*k}/{=d*k}","{=n+k}/{=d+k}","{=n*k}/{d}"],"answer":0,"hint":"Multiply the top and bottom by the same number.","explain":"{n}/{d} = ({n} × {k})/({d} × {k}) = {=n*k}/{=d*k}.","params":{"n":[1,4],"d":[2,5],"k":[2,4]},"where":"n<d"},{"type":"mc","id":"m7","prompt":"Can you add the same number to the top and bottom to get an equivalent fraction?","choices":["No, you multiply or divide both by the same number","Yes, always","Only with even numbers"],"answer":0,"hint":"Try it with 1/2 → 2/3.","explain":"1/2 isn't equal to 2/3, so adding doesn't work. Multiplying or dividing both does."}]},"practice":[{"type":"numeric","id":"p1","prompt":"1/{d} = ?/{=d*k}. What is the missing numerator?","answer":"k","hint":"The denominator was multiplied by {k}.","explain":"{d} × {k} = {=d*k}, so the numerator is 1 × {k} = {k}.","params":{"d":[2,5],"k":[2,5]}},{"type":"mc","id":"p2","prompt":"Which is NOT equal to 1/2?","choices":["3/5","4/8","5/10"],"answer":0,"hint":"Is the top exactly half of the bottom?","explain":"4/8 and 5/10 are halves, but 3 is not half of 5."},{"type":"numeric","id":"p3","prompt":"2/3 = 4/?. What is the missing denominator?","answer":6,"hint":"The numerator was doubled.","explain":"Double the denominator too: 3 × 2 = 6."},{"type":"mc","id":"p4","prompt":"Ben says 1/2 = 2/3 because he added 1 to the top and the bottom. Is he right?","choices":["No, you must multiply or divide both by the same number","Yes, he did the same to both","Yes, both are less than 1"],"answer":0,"hint":"Compare a half and two-thirds of a cake.","explain":"2/3 is bigger than 1/2. Adding the same number changes the value; multiplying both by the same number doesn't."},{"type":"numeric","id":"p5","prompt":"Fill in the box: {n}/{d} = {=n*k}/□","answer":"d*k","hint":"The numerator was multiplied by {k}.","explain":"{n} × {k} = {=n*k}, so the box is {d} × {k} = {=d*k}.","params":{"n":[1,3],"d":[2,5],"k":[2,4]},"where":"n<d"}],"explain":{"kid":["Equivalent fractions are different names for the same amount: 1/2 = 2/4 = 4/8.","Cut every piece into 2 smaller pieces. Now there are twice as many pieces, and you take twice as many. It is still the same amount."],"adult":["Multiplying or dividing the numerator and denominator by the same non-zero number gives an equivalent fraction: 1/3 = 2/6 = 3/9. On a number line, equivalent fractions mark the same point.","Adding the same number to top and bottom does not work (1/2 is not 2/3). This is one of the most common fraction misconceptions."]},"familyTip":"Fold paper strips into halves, quarters and eighths and line them up to see which lengths match.","keyIdea":"Equivalent fractions are different names for the same amount.","visual":{"type":"fracbar","caption":"Shade both bars. When the shading lines up, the fractions are equivalent.","opts":{"d":2,"shade":1,"compare":4,"compareShade":0}},"lab":{"type":"flagfrac","caption":"Flagship lab: who ate more pizza? Re-slice a chocolate bar and watch the number line: equivalent fractions are the same point.","opts":{"step":0}}},"mt_o_p-3tCxiM":{"mastery":{"passMark":4,"draw":5,"pool":[{"type":"mc","id":"m1","prompt":"What is 11/4 as a mixed number?","choices":["2 3/4","1 1/4","3 2/4"],"answer":0,"hint":"How many groups of 4 fit in 11, and what is left over?","explain":"11 ÷ 4 = 2 remainder 3. So 11/4 = 2 3/4. Reading the digits as 1 1/4 is a common slip."},{"type":"mc","id":"m2","prompt":"Write 2 3/5 as an improper fraction.","choices":["13/5","5/5","6/5"],"answer":0,"hint":"Turn each whole into fifths first.","explain":"2 wholes are 10 fifths. Add 3 fifths to get 13/5."},{"type":"mc","id":"m3","prompt":"Where does 7/4 go on a number line?","choices":["Between 1 and 2","Between 0 and 1","At 7"],"answer":0,"hint":"Is 7 quarters more or less than 4 quarters?","explain":"4 quarters make 1, and 8 quarters make 2. 7 quarters is between them, so 7/4 = 1 3/4 sits between 1 and 2."},{"type":"numeric","id":"m4","prompt":"How many thirds are in {w} wholes?","answer":"w*3","hint":"1 whole is cut into 3 thirds, so count 3 for every whole.","explain":"Each whole is 3 thirds, so {w} wholes are {w} × 3 = {=w*3} thirds. That is {=w*3}/3.","params":{"w":[2,9]}},{"type":"mc","id":"m5","prompt":"Which number sentence is true?","choices":["2/5 + 4/5 = 6/5 = 1 1/5","2/5 + 4/5 = 6/10","2/5 + 4/5 = 6/5 = 6 1/5"],"answer":0,"hint":"Fifths add to fifths, then check if you have more than 5 of them.","explain":"2 fifths and 4 fifths make 6 fifths. That is 1 whole (5 fifths) and 1 fifth more, so 6/5 = 1 1/5."},{"type":"mc","id":"m6","prompt":"What is 12/4 written as a whole number?","choices":["3","12","4"],"answer":0,"hint":"How many groups of 4 quarters can you make from 12?","explain":"12 quarters make exactly 3 groups of 4, so 12/4 = 3 with nothing left over."},{"type":"numeric","id":"m7","prompt":"A pizza is cut into 8 slices. You eat {n} slices from a pile of pizzas. Write {n}/8 as a mixed number. How many slices are in the fraction part?","answer":"n%8","hint":"Take away full pizzas of 8 slices until fewer than 8 are left.","explain":"{n} ÷ 8 = {=(n-n%8)/8} remainder {=n%8}, so there are {=n%8} slices, or {=n%8}/8, in the fraction part.","params":{"n":[9,15]}},{"type":"mc","id":"m8","prompt":"Which is the biggest?","choices":["9/4","2","7/4"],"answer":0,"hint":"Change everything to quarters: 2 is 8 quarters.","explain":"2 = 8/4, so 9/4 is biggest. 9/4 = 2 1/4, a quarter more than 2."},{"type":"mc","id":"m9","prompt":"Sam turns 4 1/3 into 4/3. What did he forget?","choices":["The 4 wholes are 12 thirds, so it should be 13/3","He should have written 41/3","Nothing, 4/3 is right"],"answer":0,"hint":"Does 4/3 still include all 4 wholes?","explain":"4/3 is only 1 1/3. The 4 wholes are 4 × 3 = 12 thirds; add 1 third to get 13/3."}]},"practice":[{"type":"mc","id":"p1","prompt":"Which of these is an improper fraction?","choices":["8/5","5/8","1 3/5"],"answer":0,"hint":"Look for a numerator that is as big as or bigger than the denominator.","explain":"8/5 has 8 on top and 5 underneath, so it is more than 1 whole. 5/8 is less than 1, and 1 3/5 is a mixed number."},{"type":"numeric","id":"p2","prompt":"A mixed number has {w} wholes and 1/{d} more. How many pieces of size 1/{d} is that in total? (Write the numerator of the improper fraction.)","answer":"w*d+1","hint":"Each whole is {d} pieces. Multiply the wholes by {d}, then add the extra 1.","explain":"{w} × {d} = {=w*d} pieces in the wholes, plus 1 more makes {=w*d+1}. So the improper fraction is {=w*d+1}/{d}.","params":{"w":[2,6],"d":[3,8]}},{"type":"numeric","id":"p3","prompt":"Write {n}/4 as a mixed number. How many wholes does it have?","answer":"(n-n%4)/4","hint":"How many groups of 4 fit into {n}? The remainder becomes the fraction part.","explain":"{n} ÷ 4 = {=(n-n%4)/4} remainder {=n%4}, so {n}/4 has {=(n-n%4)/4} wholes.","params":{"n":[9,23]}},{"type":"mc","id":"p4","prompt":"Ella says 3 2/5 = 5/5 because 3 + 2 = 5. What went wrong?","choices":["Each whole is 5 fifths, so she needed 3 × 5 + 2 = 17","She should have done 3 × 2 = 6","Nothing, 5/5 is right"],"answer":0,"hint":"How many fifths are in just one whole?","explain":"One whole is 5 fifths, so 3 wholes are 15 fifths. With the extra 2 fifths, 3 2/5 = 17/5. Adding 3 + 2 treats wholes and fifths as the same size."}],"explain":{"kid":["A fraction can be more than 1. Think of a bar cut into 4 equal parts. Each part is a quarter. 4 quarters fill the bar, so 4/4 is 1 whole. If you have 7 quarters, the first bar fills up and 3 quarters go into a second bar.","We can write that amount in two ways. 7/4 is an improper fraction. Its top number, the numerator, is bigger than its bottom number, the denominator. 1 3/4 is a mixed number. It is a whole number and a fraction side by side. Both name the same amount.","To turn an improper fraction into a mixed number, make as many wholes as you can. For 11/4, groups of 4 fit into 11 two times, with 3 left. So 11/4 is 2 3/4. This is just division with a remainder: 11 ÷ 4 = 2 r 3.","To go the other way, break every whole into pieces. In 3 2/5, each whole is 5 fifths, so 3 wholes are 15 fifths. Add the 2 fifths and you get 17 fifths, or 17/5. Wholes times the denominator, then add the numerator."],"adult":["This is the England National Curriculum Year 5 statement: recognise mixed numbers and improper fractions, convert from one form to the other, and write statements greater than 1 as a mixed number (for example 2/5 + 4/5 = 6/5 = 1 1/5). The US Common Core builds the same idea in 4.NF.B.3, where fractions are sums of unit fractions. The key fact is that n/n = 1, so every group of d pieces of size 1/d is one whole.","A common mistake is the belief that a fraction must be less than 1, so 7/4 looks impossible or gets placed between 0 and 1 on a number line. Others read the digits instead of the quantity, so 11/4 becomes 1 1/4. When converting back, children often add all the numbers (3 2/5 becomes 5/5) or drop the whole part entirely. Each slip shows the child is not yet thinking of the whole as d pieces of size 1/d.","The lab keeps the bar model in view the whole time. Your child pours quarters into bars and watches 7/4 spill into a second bar. Then they bundle 11 quarters into wholes, cut the 3 wholes of 3 2/5 into fifths and count all 17 pieces. They build targets piece by piece and place 9/4 and 2 1/2 on a number line.","Only teach the shortcut (multiply and add, or divide and keep the remainder) once the pictures make sense. Then ask your child why it works. A good answer is: each whole is worth the denominator in pieces."]},"familyTip":"Cut toast or a chocolate bar into quarters and share out 9 pieces between plates that each hold 4. Ask how many full plates and how many extra quarters there are, then write it both ways: 9/4 and 2 1/4.","keyIdea":"An improper fraction has a numerator bigger than (or equal to) its denominator, so it is worth 1 or more, like 11/4. A mixed number writes the same amount as a whole number and a proper fraction, like 2 3/4. To convert 11/4, find how many groups of 4 fit in 11 (2, remainder 3): 2 3/4. To go back, multiply the wholes by the denominator and add the numerator: 3 2/5 = (3 × 5 + 2)/5 = 17/5.","visual":{"type":"sorter","caption":"Proper fraction, improper fraction or mixed number? Drag each one, or tap it and then tap a box.","opts":{"bins":["Proper fraction","Improper fraction","Mixed number"],"items":[["3/4",0],["9/4",1],["2 1/4",2],["5/5",1],["7/10",0],["1 1/2",2],["11/3",1],["4 2/3",2]]}},"lab":{"type":"flagimpf","caption":"Flagship lab: pour quarters past a whole, bundle 11/4, cut 3 2/5 into fifths and place 9/4 on a number line.","opts":{"step":0}}},"mt_YzM5goBctT":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"A frog is on {a}/10 on a number line. It hops on {b} more tenths. It lands on ?/10. What is the top number?","answer":"a+b","hint":"Each hop adds 1 tenth. Count on from {a}.","explain":"Start at {a}/10 and count on {b} tenths: {a} + {b} = {=a+b}, so the frog lands on {=a+b}/10.","params":{"a":[1,4],"b":[1,5]}},{"type":"numeric","id":"m2","prompt":"{a} bars are shared fairly between 10 children. Each child gets ?/10 of a bar. What is the top number?","answer":"a","hint":"Cut each bar into 10. Each child gets 1 part from each bar.","explain":"Each bar is cut into 10 tenths and every child takes one tenth from each of the {a} bars, so each child gets {a}/10. That is {a} ÷ 10.","params":{"a":[2,9]}},{"type":"mc","id":"m3","prompt":"A bar is cut into 10 parts. When is each part one tenth?","choices":["When all 10 parts are the same size","Always, if there are 10 parts","When the parts are small"],"answer":0,"hint":"Think about fair shares. Do the parts need to match?","explain":"Tenths are 10 equal parts. If the parts are different sizes they are not tenths, even when there are 10 of them."},{"type":"mc","id":"m4","prompt":"What is 9/10 + 1/10?","choices":["1 whole","10/20","9/11"],"answer":0,"hint":"Add the tops. The parts are still tenths.","explain":"9 tenths and 1 tenth make 10 tenths, and 10/10 is 1 whole. Adding the bottoms to get 10/20 is a common slip."},{"type":"mc","id":"m5","prompt":"17 tenths is the same as…","choices":["1 whole and 7 tenths","17 wholes","7 wholes and 1 tenth"],"answer":0,"hint":"Swap 10 tenths for 1 whole. How many tenths are left?","explain":"10 of the tenths make 1 whole, and 7 tenths are left, so 17 tenths is 1 whole and 7/10."},{"type":"mc","id":"m6","prompt":"Count back in tenths: 6/10, 5/10, … What comes next?","choices":["4/10","5/9","4/9"],"answer":0,"hint":"Counting back changes the top number. What happens to the bottom?","explain":"Each step takes away 1 tenth, so the top goes down by 1 and the bottom stays 10: 4/10."},{"type":"mc","id":"m7","prompt":"Which is more of the same bar: 3/10 or 7/10?","choices":["7/10","3/10","They are the same"],"answer":0,"hint":"The parts are the same size. Which has more parts?","explain":"Both are tenths, so the parts are the same size. 7 parts is more than 3 parts, so 7/10 is more."}]},"practice":[{"type":"numeric","id":"p1","prompt":"A bar is cut into 10 equal parts. {a} parts are shaded. How many tenths are not shaded?","answer":"10-a","hint":"The whole bar is 10 tenths. Take away the shaded parts.","explain":"The whole is 10/10. {a}/10 are shaded, so 10 − {a} = {=10-a} tenths are not shaded: {=10-a}/10.","params":{"a":[1,9]}},{"type":"numeric","id":"p2","prompt":"How many tenths are there in {a} wholes?","answer":"a*10","hint":"Each whole is 10 tenths. Count in tens.","explain":"Each whole is 10 tenths, so {a} wholes are {a} × 10 = {=a*10} tenths.","params":{"a":[1,6]}},{"type":"numeric","id":"p3","prompt":"{a}/10 + {b}/10 = ?/10. What is the missing top number?","answer":"a+b","hint":"The parts are all tenths, so the bottom stays 10. Add the tops.","explain":"{a} tenths and {b} tenths make {=a+b} tenths, so the answer is {=a+b}/10. The bottom stays 10 because the parts are still tenths.","params":{"a":[1,4],"b":[1,5]}},{"type":"mc","id":"p4","prompt":"Which one is the same as 1 whole?","choices":["10/10","1/10","10/100"],"answer":0,"hint":"How many tenths fill the whole bar?","explain":"10/10 means all 10 of the 10 equal parts, which is the whole bar. 1/10 is just one part, and 10/100 is also one tenth."}],"explain":{"kid":["Take a bar of chocolate. Cut it into 10 parts that are all the same size. Each part is one tenth. We write it 1/10.","The bottom number tells you how many equal parts the whole has. Here it is 10. The top number tells you how many parts you have. 3/10 means 3 of the 10 parts.","Parts must be the same size. If some are big and some are small, they are not tenths, even if there are 10 of them.","You can count in tenths: 1/10, 2/10, 3/10, and on. When you get to 10/10, you have the whole bar. So 10 tenths make 1 whole."],"adult":["The English national curriculum for Year 3 asks pupils to 'count up and down in tenths' and to 'recognise that tenths arise from dividing an object into 10 equal parts and in dividing one-digit numbers or quantities by 10'. Year 4 then writes tenths as decimals, so 3/10 becomes 0.3. In the US, tenths appear in Grade 3 fractions and again in Grade 4, where 4.NF.C.6 links them to decimal notation.","A tenth is one of ten equal parts of a whole. The denominator, 10, names the size of each part. The numerator counts how many parts you have. On a number line from 0 to 1 there are ten equal steps of 1/10, so 10/10 lands on 1. Dividing by 10 makes tenths: 3 ÷ 10 = 3/10, because each of the 3 wholes gives every person one tenth.","Common mistakes: adding the bottoms as well as the tops, so 4/10 + 1/10 becomes 5/20; calling parts tenths just because there are 10, even when they are unequal; mixing up a tenth with ten or with a hundredth; and writing 9/11 for the step after 9/10. Be careful with 12 tenths: it is more than 1 whole. Swap 10 tenths for 1 whole to get 1 and 2/10.","In the lab your child shades a bar one tenth at a time up to 10/10, judges which bars are fairly cut into tenths, hops a frog along a 0 to 1 line in tenths, shares 1, 3 and 7 bars between 10 children, and builds numbers from wholes and tenths, swapping 10 tenths for 1 whole."]},"familyTip":"Line up 10 coins or pasta pieces as one whole. Take some away and say the tenth out loud: 'seven tenths left'. Then add them back one by one: 'eight tenths, nine tenths, ten tenths, one whole'.","keyIdea":"Cut one whole into 10 equal parts and each part is one tenth, written 1/10. Ten tenths make 1 whole, so 10/10 = 1. You can count up and down in tenths on a number line, and sharing 3 things between 10 people gives each person 3/10.","visual":{"type":"fracbar","caption":"The bar is cut into 10 equal parts. Shade some and read the fraction in tenths.","opts":{"d":10,"shade":3}},"lab":{"type":"flagtenth","caption":"Flagship lab: shade tenths up to 1 whole, judge fair tenths, hop on a 0-1 line, share bars between 10, and swap 10 tenths for 1 whole.","opts":{"step":0}}},"mt_IfEgu0X449":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"Ana ate {a}/12 of a cake. Ben ate {b}/12 of the same cake. How many more twelfths did Ana eat?","answer":"a-b","where":"a>b","hint":"Both are twelfths of the same cake. Take the smaller numerator from the bigger one.","explain":"Same cake, same-size twelfths. {a} twelfths is {=a-b} more than {b} twelfths, so Ana ate {=a-b} more.","params":{"a":[5,11],"b":[1,4]}},{"type":"numeric","id":"m2","prompt":"Two strips are the same length. One is cut into {a} equal parts, the other into {b}. Type how many parts are in the strip with the bigger parts.","answer":"a*(a<b)+b*(b<a)","where":"a!=b","hint":"Which strip was cut into fewer parts?","explain":"Fewer cuts make bigger parts, so the strip with the bigger parts has {=a*(a<b)+b*(b<a)} parts.","params":{"a":[2,9],"b":[2,9]}},{"type":"mc","id":"m3","prompt":"Which is bigger: 1/3 or 1/5?","choices":["1/3","1/5","They are equal"],"answer":0,"hint":"Thirds or fifths: which are bigger parts?","explain":"A whole cut into 3 parts has bigger parts than a whole cut into 5, so 1/3 > 1/5."},{"type":"mc","id":"m4","prompt":"Which is bigger: 2/5 or 4/5?","choices":["4/5","2/5","They are equal: both are fifths"],"answer":0,"hint":"The parts are the same size. Count them.","explain":"Both are fifths, so the parts match. 4 parts is more than 2 parts, so 4/5 is bigger."},{"type":"mc","id":"m5","prompt":"Which is true?","choices":["1/6 < 1/4","1/6 > 1/4","1/6 = 1/4"],"answer":0,"hint":"Sixths are smaller parts than quarters. Where does the open side face?","explain":"Sixths are smaller than quarters, so 1/6 is less: 1/6 < 1/4."},{"type":"mc","id":"m6","prompt":"Which list goes from smallest to biggest?","choices":["1/5, 1/4, 1/3","1/3, 1/4, 1/5","1/4, 1/5, 1/3"],"answer":0,"hint":"The biggest denominator makes the smallest parts.","explain":"Fifths are the smallest parts here and thirds are the biggest: 1/5, 1/4, 1/3."},{"type":"mc","id":"m7","prompt":"Mia has 1/2 of a small pizza. Leo has 1/4 of a giant pizza. Must Mia have more?","choices":["No, the pizzas are not the same size","Yes, 1/2 is always more","No, 4 is more than 2"],"answer":0,"hint":"Are the two wholes the same size?","explain":"1/2 > 1/4 only for the same whole. A quarter of a giant pizza can be more than half a small one."}]},"practice":[{"type":"numeric","id":"p1","prompt":"Which is bigger, {a}/10 or {b}/10? Type its numerator.","answer":"a*(a>b)+b*(b>a)","where":"a!=b","hint":"Both are tenths, so the parts are the same size. Which has more parts?","explain":"Same denominator, same-size parts. More parts is bigger, so the bigger one has numerator {=a*(a>b)+b*(b>a)}.","params":{"a":[1,9],"b":[1,9]}},{"type":"numeric","id":"p2","prompt":"Which is bigger, 1/{a} or 1/{b}? Type its denominator.","answer":"a*(a<b)+b*(b<a)","where":"a!=b","hint":"Fewer equal parts means bigger parts. Which denominator is smaller?","explain":"Cutting into fewer parts makes each part bigger, so the bigger unit fraction has denominator {=a*(a<b)+b*(b<a)}.","params":{"a":[2,10],"b":[2,10]}},{"type":"mc","id":"p3","prompt":"Which sign goes in the gap? 3/7 __ 5/7","choices":["<",">","="],"answer":0,"hint":"Which one is bigger? The open side faces the bigger fraction.","explain":"Both are sevenths, and 5 sevenths is more than 3 sevenths. So 3/7 < 5/7: the open side faces 5/7."},{"type":"mc","id":"p4","prompt":"Which list goes from biggest to smallest?","choices":["1/2, 1/4, 1/8","1/8, 1/4, 1/2","1/4, 1/2, 1/8"],"answer":0,"hint":"Halves are the biggest parts. Which parts are smallest?","explain":"More equal parts means smaller parts. Halves are biggest, then quarters, then eighths: 1/2, 1/4, 1/8."}],"explain":{"kid":["A fraction has two numbers. The bottom one is the denominator. It says how many equal parts the whole is cut into. The top one is the numerator. It says how many parts you have.","Cut a bar into 2 equal parts. Each part is big. Cut the same bar into 5 equal parts. Each part is small. So 1/2 is bigger than 1/5, even though 5 is a bigger number than 2.","Now look at 2/5 and 4/5. Both are fifths, so the parts are the same size. 4 parts is more than 2 parts. So 4/5 is bigger.","We use signs to show which is bigger. The sign > means greater than. The sign < means less than. The open side always faces the bigger one: 1/3 > 1/6 and 2/7 < 6/7."],"adult":["England's Year 3 programme asks pupils to 'compare and order unit fractions, and fractions with the same denominators'; the US Grade 3 standard 3.NF.A.3d asks them to compare two fractions with the same numerator or the same denominator by reasoning about their size, and to record the result with >, = or <. Both stress that the fractions must refer to the same whole.","A unit fraction has numerator 1. Its size depends only on the denominator: one whole shared into more equal parts gives smaller parts, so 1/2 > 1/3 > 1/4 > 1/5. With the same denominator the parts are equal in size, so the numerator decides: 5/8 > 3/8. With the same numerator, the smaller denominator gives the bigger fraction, which is the same idea as for unit fractions.","The most common mistake is whole-number thinking: a bigger denominator 'looks bigger', so 1/5 is called more than 1/3. Children also say 2/5 and 4/5 are equal 'because both are fifths', flip the < and > signs, and compare halves and quarters of different-sized wholes. Bars of the same length are the fix: cut them and lay the parts side by side.","In the lab your child cuts one bar into more and more parts, orders four unit fractions, shades pairs of fifths and eighths and picks the bigger, places < and > between fractions, and lays a half of a small pizza on a quarter of a giant one."]},"familyTip":"Fold two strips of paper the same length: one into halves, one into quarters. Ask, 'Which piece is bigger, one half or one quarter?' before you hold them side by side. Then shade 1 quarter and 3 quarters and ask which is more.","keyIdea":"To compare unit fractions, look at the denominator: the more equal parts a whole is cut into, the smaller each part, so 1/3 > 1/5. When two fractions have the same denominator, the parts are the same size, so the one with the bigger numerator is bigger: 4/5 > 2/5. Only compare fractions of the same whole.","visual":{"type":"fracbar","caption":"Two bars the same length: one cut into thirds, one into fifths. One third is bigger than one fifth.","opts":{"d":3,"shade":1,"compare":5,"compareShade":1}},"lab":{"type":"flagfcmp","caption":"Flagship lab: cut one bar into more parts, order unit fractions, shade and compare fifths and eighths, place < and >, and compare pizza slices.","opts":{"step":0}}},"mt_a1FdAsRKOF":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"{a}/12 + {b}/12 = ?/12. What is the missing numerator?","answer":"a+b","hint":"Twelfths plus twelfths gives twelfths. Add only the numerators.","explain":"{a} twelfths + {b} twelfths = {=a+b} twelfths, so the answer is {=a+b}/12.","params":{"a":[1,5],"b":[1,6]}},{"type":"numeric","id":"m2","prompt":"Mia walks {a}/10 of a mile before lunch and {b}/10 of a mile after lunch. How many tenths of a mile does she walk in all?","answer":"a+b","hint":"Both parts are tenths of a mile, so add the numerators.","explain":"{a} tenths + {b} tenths = {=a+b} tenths, so she walks {=a+b}/10 of a mile.","params":{"a":[1,5],"b":[1,4]}},{"type":"mc","id":"m3","prompt":"What is 7/8 − 2/8?","choices":["5/8","5/0","9/8"],"answer":0,"hint":"Take away the numerators. What size are the parts that are left?","explain":"7 eighths − 2 eighths = 5 eighths, so 5/8. 5/0 takes away the denominators, and 9/8 adds instead."},{"type":"mc","id":"m4","prompt":"Which fraction is equal to one whole?","choices":["6/6","1/6","6/12"],"answer":0,"hint":"One whole has every part. Look for the same numerator and denominator.","explain":"6/6 is all 6 sixths, so it is one whole. 1/6 is one part and 6/12 is only half."},{"type":"mc","id":"m5","prompt":"Leo says 3/7 + 2/7 = 5/14. What did he do wrong?","choices":["He added the denominators","He added the numerators","Nothing, he is right"],"answer":0,"hint":"Did the parts change size when he added them?","explain":"He added the denominators. The parts are still sevenths, so 3/7 + 2/7 = 5/7."},{"type":"mc","id":"m6","prompt":"A cake is cut into 4 equal slices. You eat 1/4. How much is left?","choices":["3/4","1/4","3/0"],"answer":0,"hint":"The whole cake is 4/4. Take away the slice you ate.","explain":"4/4 − 1/4 = 3/4. Three quarters of the cake is left."},{"type":"mc","id":"m7","prompt":"A frog starts at 2/7 on a number line and hops 3/7 to the right. Where does it land?","choices":["5/7","5/14","6/7"],"answer":0,"hint":"Each hop of 1/7 moves one step. Count on 3 sevenths from 2/7.","explain":"2/7 + 3/7 = 5/7. Counting on in sevenths is like counting on in ones."},{"type":"mc","id":"m8","prompt":"What is 1/3 + 1/3 + 1/3?","choices":["1 whole","3/9","1/3"],"answer":0,"hint":"Add the numerators: 1 + 1 + 1. Keep the denominator.","explain":"1/3 + 1/3 + 1/3 = 3/3, which is one whole. 3/9 adds the denominators too."}]},"practice":[{"type":"numeric","id":"p1","prompt":"{a}/9 + {b}/9 = ?/9. What is the missing numerator?","answer":"a+b","hint":"The parts are all ninths. Add the numerators and keep the denominator.","explain":"{a} ninths + {b} ninths = {=a+b} ninths, so {a}/9 + {b}/9 = {=a+b}/9. The denominator stays 9.","params":{"a":[1,4],"b":[1,4]}},{"type":"numeric","id":"p2","prompt":"{=a+b}/10 − {b}/10 = ?/10. What is the missing numerator?","answer":"a","hint":"Take away the numerators. The parts are still tenths.","explain":"{=a+b} tenths take away {b} tenths leaves {a} tenths, so the answer is {a}/10.","params":{"a":[1,5],"b":[1,4]}},{"type":"numeric","id":"p3","prompt":"{a}/8 + ?/8 = 1 whole. What is the missing numerator?","answer":"8-a","hint":"One whole cut into eighths is 8/8. How many more eighths do you need?","explain":"One whole is 8/8. You have {a}/8, so you need {=8-a} more eighths: {a}/8 + {=8-a}/8 = 8/8 = 1.","params":{"a":[1,7]}},{"type":"mc","id":"p4","prompt":"What is 2/5 + 2/5?","choices":["4/5","4/10","2/5"],"answer":0,"hint":"Are the parts still fifths after you add them?","explain":"2 fifths + 2 fifths = 4 fifths, so 4/5. 4/10 adds the denominators too, but the parts did not get smaller."}],"explain":{"kid":["A fraction counts equal parts. In 2/5 the bottom number, 5, is the denominator. It tells you the whole is cut into 5 equal parts, called fifths. The top number, 2, is the numerator. It counts how many parts you have.","Add 2 fifths and 2 fifths. You get 4 fifths. The parts are still fifths, so 2/5 + 2/5 = 4/5. Add the numerators. Keep the denominator the same.","Take away works the same way. You have 6 eighths and take away 3 eighths. 3 eighths are left, so 6/8 − 3/8 = 3/8. The parts are still eighths.","Five fifths fill the whole bar. So 5/5 is one whole. If you have 3/5, you need 2/5 more to make 1. On a number line, each hop of 1/7 moves you one seventh."],"adult":["England's Year 3 programme asks pupils to 'add and subtract fractions with the same denominator within one whole', for example 5/7 + 1/7 = 6/7. The US standard 4.NF.B.3a describes the same idea: adding and subtracting fractions means joining and separating parts that refer to the same whole. In the US this comes in Grade 4.","The key idea is the unit. A fifth is a unit, just like a one or a ten. Four fifths is four of that unit, so adding fifths is like counting. The denominator names the unit and does not change when you add or take away.","Common mistakes: adding the denominators as well as the numerators (2/5 + 2/5 = 4/10), taking away the denominators to get answers like 3/0, and multiplying the numerators. A quick check helps: 4/10 is less than a half, but 2/5 + 2/5 must be more than 2/5 on its own.","In the lab your child slides fifths from two bars into one bar, answers sums while a wrong 'add the bottoms' answer is drawn to scale, crosses out parts to subtract, fills a bar to make one whole, and hops in sevenths along a number line from 0 to 1."]},"familyTip":"Cut a pizza, a pancake or a sheet of paper into 8 equal slices. Each eat or move some slices and say the sum out loud: 3 eighths and 2 eighths make 5 eighths. Ask: did the slices get smaller when we added? Then ask how many more eighths would make the whole.","keyIdea":"When two fractions have the same denominator, the parts are the same size, so you add or subtract the numerators and keep the denominator: 2/5 + 2/5 = 4/5 and 6/8 − 3/8 = 3/8. Adding the denominators as well (4/10) is wrong, because the parts do not change size. When the numerator equals the denominator, as in 5/5, the fraction is one whole.","visual":{"type":"fracbar","caption":"Two bars the same length, both cut into fifths. 2/5 is shaded on one and 4/5 on the other: two more fifths, same-size parts.","opts":{"d":5,"shade":2,"compare":5,"compareShade":4}},"lab":{"type":"flagfadd","caption":"Flagship lab: slide fifths into one bar, add sevenths and eighths, cross out parts to subtract, fill to one whole and hop in sevenths.","opts":{"step":0}}},"mt_doX1BhmFgk":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"How do you write 7 hundredths as a decimal?","choices":["0.07","0.7","7.00"],"answer":0,"hint":"Hundredths go in the second place after the point.","explain":"0.07 has 0 tenths and 7 hundredths. 0.7 would be 7 tenths, which is 70 hundredths."},{"type":"numeric","id":"m2","prompt":"Start at {a} hundredths and count on {b} more hundredths. How many hundredths do you have?","answer":"a+b","hint":"Count on one hundredth at a time. Remember that 10 hundredths make 1 tenth.","explain":"{a} + {b} = {=a+b} hundredths. That is 1 tenth and {=a+b-10} hundredths, because 10 hundredths make one tenth.","params":{"a":[3,5],"b":[7,9]}},{"type":"mc","id":"m3","prompt":"Which is the same as 0.5?","choices":["50/100","5/100","1/5"],"answer":0,"hint":"0.5 is 5 tenths. Change the tenths into hundredths.","explain":"5 tenths = 50 hundredths = 50/100. 5/100 is 0.05, and 1/5 is 20/100."},{"type":"mc","id":"m4","prompt":"What is 4 ÷ 100?","choices":["0.04","0.4","400"],"answer":0,"hint":"Dividing by 100 makes a number 100 times smaller.","explain":"4 ÷ 100 = 4 hundredths = 0.04. Each digit moves two places to the right. 0.4 would be 4 ÷ 10."},{"type":"numeric","id":"m5","prompt":"A pencil is 0.{a} m long. How many centimetres is that?","answer":"10*a","hint":"0.{a} m is {a} tenths of a metre. How many hundredths is that?","explain":"0.{a} m = {a} tenths of a metre = {=10*a} hundredths of a metre = {=10*a} cm.","params":{"a":[1,9]}},{"type":"mc","id":"m6","prompt":"Which is the smallest: 0.3, 0.29 or 0.31?","choices":["0.29","0.3","0.31"],"answer":0,"hint":"Write them all as hundredths: 0.3 = 0.30.","explain":"In hundredths they are 30, 29 and 31. 29 is the smallest, so 0.29 is the smallest."},{"type":"mc","id":"m7","prompt":"What comes next? 0.97, 0.98, 0.99, …","choices":["1","0.100","0.910"],"answer":0,"hint":"One more hundredth makes 100 hundredths. How much is that?","explain":"0.99 + 0.01 = 100 hundredths, which is 1 whole. 0.100 is only 1 tenth."},{"type":"mc","id":"m8","prompt":"Mia says 0.45 is bigger than 0.5 because 45 is bigger than 5. Is she right?","choices":["No, 0.5 is 50 hundredths, so it is bigger","Yes, 45 is bigger than 5","They are equal"],"answer":0,"hint":"Write both numbers in hundredths before comparing.","explain":"0.5 = 0.50 = 50 hundredths, and 0.45 = 45 hundredths. 50 > 45, so 0.5 is bigger."}]},"practice":[{"type":"numeric","id":"p1","prompt":"How many hundredths are there in {a} tenths?","answer":"a*10","hint":"One tenth is 10 hundredths, like one column of a hundred square.","explain":"Each tenth is 10 hundredths, so {a} tenths = {a} × 10 = {=a*10} hundredths.","params":{"a":[2,9]}},{"type":"numeric","id":"p2","prompt":"{a} tenths and {b} hundredths make how many hundredths in all?","answer":"10*a+b","hint":"Change the tenths into hundredths first, then add the extra hundredths.","explain":"{a} tenths = {=10*a} hundredths. Add {b} more: {=10*a+b} hundredths, written 0.{a}{b}.","params":{"a":[1,9],"b":[1,9]}},{"type":"mc","id":"p3","prompt":"Which is bigger: 0.7 or 0.65?","choices":["0.7","0.65","They are equal"],"answer":0,"hint":"Write both as hundredths. 0.7 is 7 tenths.","explain":"0.7 = 70 hundredths and 0.65 = 65 hundredths. 70 > 65, so 0.7 is bigger even though it has fewer digits."},{"type":"numeric","id":"p4","prompt":"A ribbon is 0.{a}{b} m long. How many centimetres is that?","answer":"10*a+b","hint":"1 cm is one hundredth of a metre.","explain":"0.{a}{b} m is {=10*a+b} hundredths of a metre, and each hundredth of a metre is 1 cm, so it is {=10*a+b} cm.","params":{"a":[1,9],"b":[1,9]}},{"type":"mc","id":"p5","prompt":"What is 9 hundredths + 1 hundredth?","choices":["0.1","0.010","0.91"],"answer":0,"hint":"How many hundredths make one tenth?","explain":"9 + 1 = 10 hundredths, and 10 hundredths make 1 tenth, so the answer is 0.1. 0.010 is only 1 hundredth."}],"explain":{"kid":["Cut a cake into 10 equal slices. Each slice is one tenth. Now cut one slice into 10 tiny bits. Each bit is one hundredth of the cake.","We write one hundredth as 1/100 or 0.01. The second place after the dot shows hundredths.","Count in hundredths: 0.07, 0.08, 0.09. Next comes 10 hundredths. That is the same as one tenth, so we write 0.1.","0.4 looks short, but it is 4 tenths. That is 40 hundredths. So 0.4 is bigger than 0.35, which is 35 hundredths."],"adult":["In the National Curriculum for England, Year 4 pupils count up and down in hundredths. They recognise that hundredths arise when dividing an object by 100 and dividing tenths by 10. They write decimal equivalents of any number of tenths or hundredths, and divide one- or two-digit numbers by 10 and 100. This lesson builds on the Year 3 tenths lesson.","The key link is that the hundredths place is ten times smaller than the tenths place. A hundred square shows it well: each column is a tenth and each small square is a hundredth. So 0.37 is 3 columns and 7 squares, which is 37 hundredths. Metric length gives a real context, since 1 cm = 0.01 m.","Common mistakes: thinking a longer decimal is larger (0.35 > 0.4 because 35 > 4), writing 7 hundredths as 0.7, and counting 0.08, 0.09, 0.010 instead of 0.1. Some children treat the digits after the point as a separate whole number. Writing both numbers in hundredths, so 0.4 becomes 0.40, fixes most of these.","In the lab your child cuts a tenth of a hundred square into 10, counts from 3/100 to 12/100 on a number line, and shades 37 hundredths. Then they stretch a ribbon to 0.25 m on a metre stick and shade 0.4 and 0.35 side by side to compare them."]},"familyTip":"Use a tape measure: 1 cm is one hundredth of a metre. Measure a spoon or a shoe and say it both ways, such as 23 cm and 0.23 m. Money works too, since 1p is a hundredth of £1, so 45p is £0.45. Ask which is more, 0.5 m or 0.45 m, and check on the tape.","keyIdea":"Cut one tenth into 10 equal parts and each part is one hundredth of the whole, written 1/100 or 0.01. Ten hundredths make one tenth, so after 0.09 the count goes on to 0.1, and 100 hundredths make 1 whole. A decimal like 0.37 means 3 tenths and 7 hundredths, which is 37 hundredths. Dividing 1 by 100, or a tenth by 10, gives a hundredth; a centimetre is a hundredth of a metre. To compare decimals, write both in hundredths: 0.4 is 40 hundredths, so it is bigger than 0.35.","visual":{"type":"sorter","caption":"Is it the same as 0.3 or the same as 0.03? Drag each card, or tap it and then tap a box.","opts":{"bins":["Same as 0.3","Same as 0.03"],"items":[["3 tenths",0],["30 hundredths",0],["30/100",0],["30 cm as part of a metre",0],["3 hundredths",1],["3/100",1],["3 cm as part of a metre",1],["3 ÷ 100",1]]}},"lab":{"type":"flaghundth","caption":"Flagship lab: cut a tenth into hundredths, count past 0.09, shade 0.37 on a hundred square, stretch a ribbon to 0.25 m and compare 0.4 with 0.35.","opts":{"step":0}}},"mt_4Km38F4L-6":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Which equals 2/5?","choices":["2 ÷ 5","5 ÷ 2","2 × 5"],"answer":0,"hint":"The top number is divided by the bottom number.","explain":"2/5 means 2 ÷ 5, so 2 ÷ 5 is the match."},{"type":"numeric","id":"m2","prompt":"{a} litres of juice is poured equally into {b} bottles. How many litres go in each?","answer":"a/b","hint":"Divide the juice by the bottles.","explain":"{a} ÷ {b} = {=a/b} litres.","params":{"a":[1,9],"b":[2,5]},"where":"(a*100)%b==0 && a%b!=0"},{"type":"mc","id":"m3","prompt":"4 ÷ 3 = ?","choices":["1 1/3","3/4","1 3/4"],"answer":0,"hint":"How many whole 3s fit in 4, and what is left?","explain":"4 ÷ 3 is 1 remainder 1, and the 1 left over is shared into thirds: 1 1/3."},{"type":"numeric","id":"m4","prompt":"{b} friends share {a} chocolate bars equally. How many bars does each get? Give a decimal.","answer":"a/b","hint":"Divide the number of bars by the number of friends.","explain":"{a} ÷ {b} = {=a/b} bars each.","params":{"a":[1,9],"b":[2,5]},"where":"(a*100)%b==0 && a%b!=0"},{"type":"mc","id":"m5","prompt":"3 pizzas are shared by 4 people. What does each person get?","choices":["3/4 of a pizza","4/3 of a pizza","1 pizza"],"answer":0,"hint":"Each person gets 3 ÷ 4 of a pizza.","explain":"3 ÷ 4 = 3/4, so each person gets 3/4 of a pizza."},{"type":"mc","id":"m6","prompt":"Which story fits 2/3?","choices":["2 sandwiches shared by 3 people","3 sandwiches shared by 2 people","2 sandwiches and 3 more"],"answer":0,"hint":"2/3 means 2 things shared between 3.","explain":"2 shared between 3 is 2 ÷ 3 = 2/3."},{"type":"numeric","id":"m7","prompt":"{a} kg of flour is split into {b} equal bags. How many kg go in each bag?","answer":"a/b","hint":"Divide the kilograms of flour by the number of bags.","explain":"{a} ÷ {b} = {=a/b} kg.","params":{"a":[1,9],"b":[2,5]},"where":"(a*100)%b==0 && a%b!=0"}]},"practice":[{"type":"mc","id":"p1","prompt":"5 ÷ 8 as a fraction is…","choices":["5/8","8/5","5/13"],"answer":0,"hint":"The top number is divided by the bottom.","explain":"5 ÷ 8 is written as the fraction 5/8."},{"type":"numeric","id":"p2","prompt":"{a} pizzas are shared equally by {b} people. How much pizza does each person get? Give a decimal.","answer":"a/b","hint":"Work out {a} ÷ {b}.","explain":"{a} ÷ {b} = {=a/b} of a pizza each.","params":{"a":[1,9],"b":[2,5]},"where":"(a*100)%b==0 && a%b!=0"},{"type":"numeric","id":"p3","prompt":"{a} metres of ribbon is cut into {b} equal pieces. How long is each piece, in metres?","answer":"a/b","hint":"Length ÷ number of pieces.","explain":"{a} ÷ {b} = {=a/b} m.","params":{"a":[1,9],"b":[2,5]},"where":"(a*100)%b==0 && a%b!=0"},{"type":"mc","id":"p4","prompt":"7 cakes are shared equally between 3 children. Each child gets…","choices":["2 1/3 cakes","3/7 of a cake","2 cakes, with 1 left over each"],"answer":0,"hint":"Work out 7 ÷ 3 as a mixed number.","explain":"7 ÷ 3 = 2 remainder 1, and the 1 left over is shared too: 2 1/3."}],"explain":{"kid":["A fraction is a division. 3/4 means 3 ÷ 4.","Share 3 pizzas between 4 people. Cut each pizza into 4 slices. Each person takes one slice from each pizza. That is 3 slices, and each slice is a quarter, so each person gets 3/4 of a pizza."],"adult":["a/b = a ÷ b for any whole numbers. Sharing 7 cakes between 3 people gives 7/3 = 2 1/3 cakes each.","In word problems, decide what is being shared and between how many. The answer may be a fraction or a mixed number. Check: the answer times the number of people should give back the total."]},"familyTip":"Share 2 sandwiches between 3 people for real. How much does each person get? Write it as a fraction.","keyIdea":"a/b means a ÷ b: sharing a wholes equally between b people gives each person a/b.","visual":{"type":"wholes","caption":"3 pizzas shared between 4 people. Press “Share out” to see why each person gets 3/4.","opts":{"a":3,"b":4}}},"mt_hyvHv2BCwb":{"mastery":{"passMark":4,"draw":5,"pool":[{"type":"mc","id":"m1","prompt":"Which slice of the same pizza is bigger?","choices":["A slice when 2 share","A slice when 8 share","They are the same"],"answer":0,"hint":"Fewer people share the pizza in one of them.","explain":"Shared by 2, each slice is a half. Shared by 8, each slice is much smaller."},{"type":"mc","id":"m2","prompt":"Why is a quarter smaller than a half of the same shape?","choices":["The shape is cut into more equal parts","Because 4 is a small number","Because quarters are always square"],"answer":0,"hint":"How many parts is the shape cut into for quarters?","explain":"For quarters the same shape is cut into 4 equal parts instead of 2, so each part is smaller."},{"type":"mc","id":"m3","prompt":"A circle is cut into 2 parts. One part is big and one is small. Are they halves?","choices":["No, halves are equal","Yes, there are 2 parts","Yes, it is a circle"],"answer":0,"hint":"What must be true about halves?","explain":"Halves are 2 equal parts. A big part and a small part are not halves."},{"type":"numeric","id":"m4","prompt":"{n} friends share one pizza fairly. Then {k} more friends come. How many equal slices are needed now?","answer":"n+k","hint":"Everyone needs one equal slice, the new friends too.","explain":"{n} + {k} = {=n+k} people, so the pizza is cut into {=n+k} equal slices. More slices means each one is smaller.","params":{"n":[2,4],"k":[1,4]}},{"type":"mc","id":"m5","prompt":"Two people share a pizza. Then two more people come. What should you do so that it is fair?","choices":["Cut each half into 2 equal parts","Give the new people the crusts","Cut one more slice"],"answer":0,"hint":"Now 4 people need equal shares.","explain":"Cut each half in two. That gives 4 equal quarters, one for each person, and each is smaller than a half."},{"type":"numeric","id":"m6","prompt":"Each pizza is cut into quarters. How many quarters are in {w} whole pizzas?","answer":"4*w","hint":"One whole pizza is 4 quarters.","explain":"Each whole is 4 quarters, so {w} pizzas make 4 × {w} = {=4*w} quarters.","params":{"w":[1,5]}},{"type":"mc","id":"m7","prompt":"Fold a paper in half, then fold it in half again. What are the parts called?","choices":["Quarters","Halves","Thirds"],"answer":0,"hint":"Count the parts when you open it.","explain":"Two folds make 4 equal parts, and 4 equal parts are quarters."},{"type":"numeric","id":"m8","prompt":"A pizza is cut into {n} equal slices. {k} slices are eaten. How many slices are left?","answer":"n-k","hint":"Take the eaten slices away from all the slices.","explain":"{n} − {k} = {=n-k}. There are {=n-k} slices left.","params":{"n":[6,8],"k":[1,4]}},{"type":"mc","id":"m9","prompt":"Sam has a half of a small cookie. Ana has a quarter of a giant pizza. Can we say Sam's piece is bigger?","choices":["No, the wholes are different sizes","Yes, a half is always bigger","Yes, cookies are sweet"],"answer":0,"hint":"Halves and quarters can only be compared on the same whole.","explain":"A half is bigger than a quarter only when both come from the same whole. A giant pizza's quarter can be bigger than a tiny cookie's half."}]},"practice":[{"type":"mc","id":"p1","prompt":"The same cake is cut into halves and into quarters. Which piece is bigger?","choices":["A half","A quarter","They are the same size"],"answer":0,"hint":"Lay a quarter on top of a half. Does it cover it all?","explain":"A half is bigger. A quarter covers only part of a half, because 2 quarters make 1 half."},{"type":"numeric","id":"p2","prompt":"A cake is cut into halves. Then each half is cut into {k} equal pieces. How many pieces are there now?","answer":"2*k","hint":"There are 2 halves, and each one now has {k} pieces.","explain":"2 halves with {k} pieces each make 2 × {k} = {=2*k} pieces. More pieces, so each piece is smaller than a half.","params":{"k":[2,6]}},{"type":"mc","id":"p3","prompt":"A pizza is shared by 2 people, then the same pizza is shared by 4 people. What happens to each slice?","choices":["It gets smaller","It gets bigger","It stays the same"],"answer":0,"hint":"The pizza stays the same size. It is cut into more parts.","explain":"More people share the same pizza, so each person gets a smaller slice."},{"type":"numeric","id":"p4","prompt":"How many quarters fit exactly on {h} halves of the same shape?","answer":"2*h","hint":"Two quarters cover one half.","explain":"Each half takes 2 quarters, so {h} halves take {=2*h} quarters.","params":{"h":[1,5]}},{"type":"mc","id":"p5","prompt":"A sandwich is cut into 4 parts. Two parts are wide and two are thin. Are they quarters?","choices":["No, the parts are not equal","Yes, there are 4 parts","Yes, if you cut it with a knife"],"answer":0,"hint":"Quarters must all be the same size.","explain":"Quarters are 4 equal parts. Wide and thin parts are not equal, so they are not quarters."}],"explain":{"kid":["Think of one pizza. If 2 of you share it, you each get a big slice. That slice is a half.","Now 4 of you share the same pizza. It is cut into 4 slices. Each slice is a quarter. A quarter is smaller than a half.","More people share, so each slice gets smaller. The pizza did not change. It was cut into more parts. Fair shares are all the same size. If one part is big and one is small, they are not halves or quarters.","Fold a paper in half. You get 2 parts. Fold it again. You get 4 parts. Two quarters fit on one half."],"adult":["Ages 6 to 7. This is US Common Core 1.G.3: partition circles and rectangles into two and four equal shares, use the words halves, fourths and quarters, and understand that decomposing into more equal shares creates smaller shares. It matches the Year 1 fractions aims in the National Curriculum in England. Key words: whole, equal shares, half, halves, quarter, fourth, smaller.","The big idea runs against counting. Children know that 4 is more than 2, so many expect a quarter to be bigger than a half. The fix is to compare pieces of the same whole: lay one quarter on one half and see the gap. Fraction symbols such as one half and one quarter come later, in Year 2 and in grade 3.","Common mistakes: thinking a quarter is bigger because 4 is bigger than 2; calling any four pieces quarters, even when they are different sizes; thinking two folds give three parts; and comparing pieces from wholes of different sizes. A quarter of a big pizza can be bigger than a half of a tiny one, so always use the same whole.","In the lab your child adds friends to one pizza and watches one share shrink. They fold paper up to 8 parts, cover a half with two quarters and judge five cuts as equal or not. Last, they line up slices shared by 2, 3, 4, 6 and 8 people, from biggest to smallest."]},"familyTip":"Fold a slice of bread or a sheet of paper in half and ask which piece your child wants. Fold the other one in half twice. Put one quarter on one half: which is bigger? Then ask: if granny joins us, will our cake slices get bigger or smaller?","keyIdea":"When one shape is cut into more equal shares, each share is smaller. A pizza shared by 2 gives halves; the same pizza shared by 4 gives quarters, and a quarter is smaller than a half. Two quarters cover one half exactly. Equal shares must all be the same size: four parts of different sizes are not quarters.","visual":{"type":"fracbar","caption":"One bar cut into halves and the same bar cut into quarters. One half is shaded and one quarter is shaded: which shaded piece is bigger?","opts":{"d":2,"shade":1,"compare":4,"compareShade":1}},"lab":{"type":"flagmoresh","caption":"Flagship lab: add friends to one pizza, fold paper again and again, cover a half with quarters, judge fair cuts and line up slices from biggest to smallest.","opts":{"step":0}}},"mt_933BohS9BH":{"mastery":{"passMark":4,"draw":5,"pool":[{"type":"mc","id":"m1","prompt":"Which is bigger: 1.99 or 2.1?","choices":["2.1","1.99","They are equal"],"answer":0,"hint":"Start with the ones before any digit after the point.","explain":"2.1 has 2 ones and 1.99 has 1 one. The ones decide, so 2.1 is bigger."},{"type":"mc","id":"m2","prompt":"Is 0.6 equal to 0.60?","choices":["Yes, both are 6 tenths","No, 0.60 is bigger","No, 0.6 is bigger"],"answer":0,"hint":"Does the zero on the end add any hundredths?","explain":"0.60 is 6 tenths and 0 hundredths, the same as 0.6. A zero on the end changes nothing."},{"type":"mc","id":"m3","prompt":"Which is smallest: 0.09, 0.1 or 0.089?","choices":["0.089","0.09","0.1"],"answer":0,"hint":"Give them all three places: 0.090, 0.100, 0.089.","explain":"As thousandths they are 90, 100 and 89, so 0.089 is smallest and 0.1 is biggest."},{"type":"mc","id":"m4","prompt":"In 0.38 and 0.4, which place decides which is bigger?","choices":["the tenths","the hundredths","the ones"],"answer":0,"hint":"Find the first place, from the left, where the digits differ.","explain":"Both have 0 ones. The tenths are 3 and 4, so the tenths decide: 0.4 > 0.38."},{"type":"mc","id":"m5","prompt":"Which is bigger: 0.3 or 0.31?","choices":["0.31","0.3","They are equal"],"answer":0,"hint":"Write 0.3 as 0.30 so both have two places.","explain":"0.30 and 0.31 have the same tenths, and 1 hundredth beats 0, so 0.31 is bigger."},{"type":"numeric","id":"m6","prompt":"How many thousandths are in 0.{a}0{b}?","answer":"100*a+b","hint":"A tenth is 100 thousandths. There are no hundredths here.","explain":"0.{a}0{b} is {a} tenths, 0 hundredths and {b} thousandths: {=100*a+b} thousandths.","params":{"a":[1,9],"b":[1,9]}},{"type":"numeric","id":"m7","prompt":"Write 0.{a} and 0.{b}{c} as hundredths. How many hundredths bigger is 0.{a}?","answer":"10*a-10*b-c","hint":"Add a zero to 0.{a} so both have two places.","explain":"0.{a} = {=10*a} hundredths and 0.{b}{c} = {=10*b+c} hundredths, so 0.{a} is bigger by {=10*a-10*b-c} hundredths.","params":{"a":[2,9],"b":[1,8],"c":[1,9]},"where":"b<a"},{"type":"mc","id":"m8","prompt":"Why is 0.405 smaller than 0.45?","choices":["Both have 4 tenths, and 0 hundredths is less than 5 hundredths","It has more digits","405 is less than 45"],"answer":0,"hint":"Line them up and compare from the left.","explain":"The tenths match, and the hundredths are 0 and 5. The number of digits does not decide, and 405 is more than 45 anyway."},{"type":"mc","id":"m9","prompt":"A runner's times are 9.85 seconds and 9.9 seconds. Which time is shorter?","choices":["9.85 seconds","9.9 seconds","They are the same"],"answer":0,"hint":"Write 9.9 as 9.90 and compare the tenths.","explain":"9.85 has 8 tenths and 9.90 has 9 tenths, so 9.85 is the smaller number and the shorter time."}]},"practice":[{"type":"mc","id":"p1","prompt":"Which is bigger: 0.45 or 0.405?","choices":["0.45","0.405","They are equal"],"answer":0,"hint":"Line up the points. Both have 4 tenths. Look at the hundredths.","explain":"0.45 has 5 hundredths and 0.405 has 0 hundredths, so 0.45 is bigger, even though 0.405 has more digits."},{"type":"numeric","id":"p2","prompt":"{a} tenths is the same as how many hundredths?","answer":"10*a","hint":"Each tenth splits into 10 hundredths.","explain":"{a} tenths × 10 = {=10*a} hundredths, so 0.{a} is the same as 0.{a}0.","params":{"a":[1,9]}},{"type":"mc","id":"p3","prompt":"Which sign makes this true? 0.3 ? 0.25","choices":[">","<","="],"answer":0,"hint":"Compare the tenths first: 3 and 2.","explain":"0.3 has 3 tenths and 0.25 has 2 tenths, so 0.3 > 0.25. As hundredths it is 30 and 25."},{"type":"numeric","id":"p4","prompt":"Write 0.{a}{b} as a number of hundredths.","answer":"10*a+b","hint":"Each tenth is 10 hundredths. Add the hundredths digit.","explain":"0.{a}{b} is {a} tenths and {b} hundredths, which is {=10*a+b} hundredths.","params":{"a":[1,9],"b":[1,9]}},{"type":"mc","id":"p5","prompt":"Which list is in order, smallest first?","choices":["3.04, 3.14, 3.142, 3.2","3.2, 3.04, 3.14, 3.142","3.142, 3.14, 3.04, 3.2"],"answer":0,"hint":"All have 3 ones. Compare tenths, then hundredths, then thousandths.","explain":"3.04 has 0 tenths, 3.14 and 3.142 have 1 tenth, and 3.2 has 2 tenths. 3.14 = 3.140 is less than 3.142."}],"explain":{"kid":["To compare two decimals, write one under the other with the points lined up. Start at the left. Look at the ones, then the tenths, then the hundredths. The first place where the digits are not the same tells you which number is bigger.","More digits does not make a number bigger. 0.405 has more digits than 0.45, but it is smaller. Both have 4 tenths. Then 0.45 has 5 hundredths, and 0.405 has none.","Fewer digits does not make it bigger either. 0.3 is more than 0.25, because 3 tenths beats 2 tenths. But 0.3 is less than 0.31.","A zero on the end changes nothing. 0.7, 0.70 and 0.700 are the same number. So you can add zeros to make both numbers the same length. Then 0.40 and 0.38 compare like 40 and 38."],"adult":["Ages 9 to 10. In England, Year 4 pupils compare numbers with the same number of decimal places up to two decimal places, and Year 5 pupils read, write, order and compare numbers with up to three decimal places. In the US this is Common Core 5.NBT.A.3b: compare two decimals to thousandths based on the meanings of the digits in each place, using >, = and < symbols to record the results.","It works because of place value. Each place is worth ten times the place to its right, so one unit in an earlier place outweighs everything after it: 0.1 is more than 0.099. Trailing zeros are equivalent fractions: 0.7 = 7/10 = 70/100 = 700/1000. That is why padding with zeros is allowed, and why, once both numbers have the same number of places, they compare like whole numbers of hundredths or thousandths. A number line you can zoom into and a hundred square (one column is a tenth, one square a hundredth) make this visible.","Common mistakes, well documented in research on decimal misconceptions: longer is larger (whole-number thinking, so 0.405 looks bigger than 0.45), shorter is larger (believing tenths always beat hundredths, so 0.3 looks bigger than 0.31), thinking 0.70 is bigger than 0.7, and ignoring the whole-number part (1.99 looks bigger than 2.1 because 99 beats 1). Reading 0.45 as point forty-five feeds the first slip.","In the lab your child places 0.45, 0.405, 0.3 and 0.25 on a number line that zooms from tenths into thousandths, taps the first place that differs in five pairs on a place value chart, adds zeros before choosing <, = or >, shades 0.3, 0.25, 0.06 and 0.6 on hundred squares, and orders two sets such as 3.2, 3.14, 3.142 and 3.04."]},"familyTip":"Use race times or prices. Ask which is faster, 9.85 seconds or 9.9 seconds, and how your child knows. Write the two numbers one above the other with the points lined up, and run a finger along from the left until the digits differ. Say decimals digit by digit (zero point four five, not zero point forty-five), because forty-five makes it sound like a whole number.","keyIdea":"To compare decimals, line up the decimal points and compare place by place from the left: ones, then tenths, then hundredths, then thousandths. The first place where the digits differ decides. More digits does not mean bigger: 0.45 > 0.405, because both have 4 tenths but 0.45 has 5 hundredths and 0.405 has none. Fewer digits does not mean bigger either: 0.3 > 0.25, but 0.3 < 0.31. Zeros on the end change nothing (0.7 = 0.70 = 0.700), so you can add them to give both numbers the same number of places and then compare them like whole numbers: 0.40 > 0.38. Record the result with <, = or >.","visual":{"type":"sorter","caption":"Less than a half or more than a half? Drag each card, or tap it and then tap a box.","opts":{"bins":["less than 0.5","more than 0.5"],"items":[["0.45",0],["0.6",1],["0.405",0],["0.52",1],["0.499",0],["0.7",1],["0.09",0]]}},"lab":{"type":"flagdeccmp","caption":"Flagship lab: zoom a number line, find the place that decides, add zeros to compare fairly, shade hundred squares, and put decimals in order.","opts":{"step":0}}},"mt_VKW8lOcFaw":{"mastery":{"passMark":4,"draw":5,"pool":[{"type":"mc","id":"m1","prompt":"Without multiplying, which product is less than 50?","choices":["50 × 7/8","50 × 9/8","50 × 8/8"],"answer":0,"hint":"Only a factor less than 1 gives a product less than 50.","explain":"7/8 is less than 1, so 50 × 7/8 is less than 50. 9/8 is more than 1 and 8/8 is exactly 1."},{"type":"mc","id":"m2","prompt":"Ava says, 'Multiplying always makes a number bigger.' Which example proves her wrong?","choices":["10 × 1/2 = 5","10 × 2 = 20","10 × 3/2 = 15"],"answer":0,"hint":"Look for a factor less than 1.","explain":"10 × 1/2 = 5, which is less than 10. Multiplying by a factor less than 1 makes the number smaller."},{"type":"numeric","id":"m3","prompt":"A map distance of {a} cm is scaled by 5/2 for a poster. How many cm is it on the poster?","answer":"a*5/2","hint":"Half of the distance, times 5.","explain":"{a} ÷ 2 × 5 = {=a*5/2} cm. The factor 5/2 is more than 1, so the poster distance is longer.","params":{"a":[2,20]},"where":"a%2==0"},{"type":"mc","id":"m4","prompt":"Which is greatest?","choices":["24 × 5/4","24 × 1","24 × 3/4"],"answer":0,"hint":"Same 24 each time. Find the biggest factor.","explain":"5/4 is the biggest factor, and the only one more than 1, so 24 × 5/4 (30) is the greatest."},{"type":"mc","id":"m5","prompt":"What is 6/6 × 13?","choices":["13","78","more than 13"],"answer":0,"hint":"What is 6/6 as a whole number?","explain":"6/6 = 1, so 6/6 × 13 = 13. 78 comes from multiplying by the top 6 and ignoring the bottom 6."},{"type":"mc","id":"m6","prompt":"A photo 12 cm wide is scaled by 2/3. How wide is it now?","choices":["8 cm","18 cm","14 cm"],"answer":0,"hint":"Find a third of 12, then take 2 of them.","explain":"12 ÷ 3 × 2 = 8 cm. 18 cm is 12 ÷ 2/3, and 14 cm is 12 + 2: neither is scaling by 2/3."},{"type":"mc","id":"m7","prompt":"Which multiplier turns 3/4 into an equal fraction with 12 parts?","choices":["3/3","4/4","12/12"],"answer":0,"hint":"How many times 4 makes 12?","explain":"4 × 3 = 12, so 3/4 × 3/3 = 9/12. 4/4 gives sixteenths and 12/12 gives 48ths."},{"type":"numeric","id":"m8","prompt":"{a} people share a recipe that uses 300 g of rice for 4 people. How many grams do {a} people need?","answer":"300*a/4","hint":"Scale 300 g by the factor {a}/4.","explain":"300 × {a}/4 = {=300*a/4} g. The factor is more than 1 when there are more than 4 people and less than 1 when there are fewer.","params":{"a":[2,10]},"where":"a%2==0"}]},"practice":[{"type":"mc","id":"p1","prompt":"Without working it out: is 36 × 5/9 more than 36, less than 36 or equal to 36?","choices":["less than 36","more than 36","equal to 36"],"answer":0,"hint":"Compare the factor 5/9 with 1 whole.","explain":"5/9 is less than 1, so you take only part of 36. The product is less than 36 (it is 20)."},{"type":"numeric","id":"p2","prompt":"A ribbon is {a} cm long. It is scaled by 3/2. How long is it now, in cm?","answer":"a*3/2","hint":"Find half of the length, then take 3 halves.","explain":"{a} ÷ 2 × 3 = {=a*3/2} cm. The factor 3/2 is more than 1, so the ribbon got longer.","params":{"a":[4,40]},"where":"a%2==0"},{"type":"numeric","id":"p3","prompt":"A ribbon is {a} cm long. It is scaled by 3/4. How long is it now, in cm?","answer":"a*3/4","hint":"Find a quarter of the length, then take 3 quarters.","explain":"{a} ÷ 4 × 3 = {=a*3/4} cm. The factor 3/4 is less than 1, so the ribbon got shorter.","params":{"a":[4,48]},"where":"a%4==0"},{"type":"mc","id":"p4","prompt":"Which is larger: 15 × 4/5 or 15 × 6/5?","choices":["15 × 6/5","15 × 4/5","They are equal"],"answer":0,"hint":"Both start at 15. Which factor is bigger?","explain":"6/5 is more than 1 and 4/5 is less than 1, so 15 × 6/5 (18) is larger than 15 × 4/5 (12)."},{"type":"mc","id":"p5","prompt":"2/3 × 5/5 = 10/15. How does 10/15 compare with 2/3?","choices":["It is the same amount","It is more","It is less"],"answer":0,"hint":"What is 5/5 as a whole number?","explain":"5/5 is 1 whole, and multiplying by 1 changes nothing. 10/15 is the same amount as 2/3, cut into smaller parts."}],"explain":{"kid":["Times can mean scale, or resize. 8 × 2 makes 8 twice as big. 8 × 3/2 makes it one and a half times as big: 12. You can tell the size of an answer before you work it out. Look at the number you multiply by, called the factor. Is it more than 1, less than 1, or just 1?","If the factor is more than 1, the answer is bigger than the start. If it is less than 1, the answer is smaller, because you only take part of the start. 8 × 3/4 is 6, less than 8.","If the factor is 1, the answer stays the same. 4/4 is 1 whole, so 3/5 × 4/4 is still 3/5. It is just written as 12/20, with more, smaller parts.","To compare 12 × 2/3 and 12 × 3/4, you do not need to multiply. Both start at 12, and 3/4 is the bigger factor, so 12 × 3/4 is bigger."],"adult":["This is Common Core 5.NF.B.5: interpret multiplication as scaling, comparing the size of a product to one factor from the size of the other factor (5a), and explaining why a fraction greater than 1 gives a product greater than the given number, a fraction less than 1 gives a smaller product, and multiplying by n/n gives an equivalent fraction (5b). In England, Year 5 and Year 6 pupils solve problems that involve scaling by simple fractions.","The key move is reasoning about size without calculating: for a positive number b, a × b is greater than a when b > 1, less than a when 0 < b < 1, and equal to a when b = 1. The ribbon in the lab is a length model of this. The n/n step links scaling to equivalent fractions: 3/5 × 4/4 = 12/20, because each fifth is cut into four equal parts.","Common mistakes: believing that multiplication always makes bigger (and division always makes smaller), which comes from whole-number work; thinking that any fraction shrinks, even 5/2; reading 12/20 as more than 3/5 because the numbers are bigger; multiplying only the top of n/n (7/7 × 15 = 105); and confusing scaling with adding, as in 10 scaled by 2/5 becoming 12.","Ask children to say 'more than, less than or equal to the start' before they calculate, then check. Contexts such as recipes, map scales and resizing a photo make the factor's meaning concrete."]},"familyTip":"Take a recipe for 4 people and scale it together: what happens to 300 g of flour for 2 people (× 1/2) or for 6 people (× 3/2)? Before working it out, say whether the new amount will be more or less than 300 g, and why.","keyIdea":"Multiplying can be read as scaling: resizing a number by a factor. Compare the factor with 1 and you know the size of the answer without working it out. A factor more than 1 makes the product bigger than the number you started with (8 × 3/2 = 12). A factor less than 1 makes it smaller (8 × 3/4 = 6). A factor of exactly 1 keeps it the same, and any fraction n/n is 1, so 3/5 × 4/4 = 12/20 is the same amount as 3/5. For the same starting number, the bigger factor gives the bigger product.","visual":{"type":"sorter","caption":"Will the product be less than 20, exactly 20 or more than 20? Drag each card, or tap it and then tap a box.","opts":{"bins":["less than 20","exactly 20","more than 20"],"items":[["20 × 3/4",0],["20 × 5/5",1],["20 × 1 1/3",2],["20 × 9/10",0],["20 × 2",2],["20 × 1",1]]}},"lab":{"type":"flagxscale","caption":"Flagship lab: stretch and shrink a ribbon by a scale factor, sort products against 9 without multiplying, pick the larger product, and multiply 3/5 by 4/4.","opts":{"step":0}}},"mt_-hTTat0mBR":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"What is half of {=2*n}?","answer":"n","hint":"Two equal groups.","explain":"Half of {=2*n} is {n}.","params":{"n":[1,8]}},{"type":"mc","id":"m2","prompt":"How many halves make a whole?","choices":["2","1","4"],"answer":0,"hint":"Two parts.","explain":"Two halves make one whole."},{"type":"numeric","id":"m3","prompt":"Sam eats half of {=2*n} grapes. How many does Sam eat?","answer":"n","hint":"Share fairly in two.","explain":"{=2*n} ÷ 2 = {n} grapes.","params":{"n":[2,7]}},{"type":"mc","id":"m4","prompt":"Which shows a half?","choices":["A square cut into 2 same-size parts, one shaded","A square cut into 3 parts, one shaded","A square cut into 2 different parts, one shaded"],"answer":0,"hint":"Two equal parts.","explain":"Only the first has two equal parts."},{"type":"mc","id":"m5","prompt":"Half an apple and half an apple make…","choices":["one whole apple","a quarter","two apples"],"answer":0,"hint":"2 halves.","explain":"Two halves make a whole."},{"type":"mc","id":"m6","prompt":"Is half of 10 the same as 5?","choices":["Yes","No"],"answer":0,"hint":"Share 10 in two.","explain":"10 shared in two is 5 each."},{"type":"mc","id":"m7","prompt":"A sandwich is cut into 2 equal parts. You eat 1. What did you eat?","choices":["Half","All of it","A quarter"],"answer":0,"hint":"One of two equal parts.","explain":"One of two equal parts is a half."}]},"practice":[{"type":"mc","id":"p1","prompt":"A pizza is cut into 2 equal parts. Each part is…","choices":["a half","a quarter","a whole"],"answer":0,"hint":"Two equal parts.","explain":"Two equal parts: each is a half."},{"type":"numeric","id":"p2","prompt":"What is half of {=2*n} sweets?","answer":"n","hint":"Share them into 2 fair piles.","explain":"{=2*n} shared into 2 piles is {n} each.","params":{"n":[2,6]}},{"type":"mc","id":"p3","prompt":"A cake is cut into one big part and one small part. Are they halves?","choices":["No, they are not the same size","Yes","Only the big part"],"answer":0,"hint":"Halves must match.","explain":"Halves are equal, so these are not halves."},{"type":"numeric","id":"p4","prompt":"Half of the {=2*n} cars are red. How many are red?","answer":"n","hint":"Share into 2 equal groups.","explain":"{=2*n} ÷ 2 = {n}.","params":{"n":[1,5]}}],"explain":{"kid":["Cut a cake into two parts that are the same size. Each part is a half.","If one part is big and one is small, they are not halves."],"adult":["A half is one of two equal parts of a whole shape or a group. The key word is equal: two unequal pieces are not halves.","Children meet halves first with shapes and food, then with groups: half of 8 sweets is 4, because 8 shared fairly between two is 4 each."]},"familyTip":"Fold a piece of paper in half. Check the two parts match exactly. Then share 6 grapes into two fair halves.","keyIdea":"A half is one of two equal parts.","visual":{"type":"fracbar","caption":"Tap the parts. Shade one of the two equal parts: that is a half.","opts":{"d":2,"shade":1,"pie":true}}},"mt_g3W0mdADVu":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"A quarter of {=4*n} cars is how many?","answer":"n","hint":"Four equal groups.","explain":"Share {=4*n} cars into 4 equal groups: {=4*n} ÷ 4 = {n}.","params":{"n":[1,6]}},{"type":"mc","id":"m2","prompt":"How many quarters make a whole?","choices":["4","2","3"],"answer":0,"hint":"A whole is cut into four equal parts.","explain":"Four quarters make one whole."},{"type":"numeric","id":"m3","prompt":"Mia eats 2 quarters of a pizza cut into 4. How many slices are left?","answer":2,"hint":"Take the 2 eaten slices away from 4.","explain":"4 slices take away 2 eaten leaves 2 slices."},{"type":"mc","id":"m4","prompt":"Which is bigger?","choices":["A half","A quarter","They are the same"],"answer":0,"hint":"Fewer parts, bigger parts.","explain":"A half is two quarters, so it is bigger."},{"type":"numeric","id":"m5","prompt":"Ben has {=4*n} sweets and gives away a quarter. How many does he give away?","answer":"n","hint":"Share the sweets into 4 equal groups.","explain":"A quarter of {=4*n} is {=4*n} ÷ 4 = {n} sweets.","params":{"n":[2,5]}},{"type":"mc","id":"m6","prompt":"A square is cut into 4 parts of different sizes. Is each a quarter?","choices":["No","Yes"],"answer":0,"hint":"Quarters are equal.","explain":"Quarters must all be the same size."},{"type":"mc","id":"m7","prompt":"Two quarters of a cake are the same as…","choices":["half the cake","the whole cake","a quarter"],"answer":0,"hint":"Two of the four equal parts is how much?","explain":"2 of 4 equal parts is a half."}]},"practice":[{"type":"mc","id":"p1","prompt":"A pie is cut into 4 equal parts. One part is…","choices":["a quarter","a half","a third"],"answer":0,"hint":"Four equal parts.","explain":"One of four equal parts is a quarter."},{"type":"numeric","id":"p2","prompt":"What is a quarter of {=4*n}?","answer":"n","hint":"Share into 4 equal groups.","explain":"Share {=4*n} into 4 equal groups: {=4*n} ÷ 4 = {n}.","params":{"n":[1,5]}},{"type":"mc","id":"p3","prompt":"How many quarters make a half?","choices":["2","4","1"],"answer":0,"hint":"Fold a half in half.","explain":"Two quarters make a half."},{"type":"numeric","id":"p4","prompt":"Half of {=4*n} is…","answer":"2*n","hint":"Share the number into 2 equal groups.","explain":"Share {=4*n} into 2 equal groups: {=4*n} ÷ 2 = {=2*n}.","params":{"n":[1,5]}}],"explain":{"kid":["Cut a cake into 4 parts that are all the same size. Each part is a quarter.","Two quarters are as big as one half."],"adult":["A quarter is one of four equal parts, so it is half of a half. Fold a paper square in half, then in half again, and you get quarters.","For groups, find a quarter by sharing between four: a quarter of 12 is 3. Two quarters equal one half, which is a first taste of equivalent fractions."]},"familyTip":"Fold a paper square into quarters. Shade one quarter, then two. Is two quarters the same as half?","keyIdea":"A quarter is one of four equal parts; two quarters make a half.","visual":{"type":"fracbar","caption":"One bar in halves, one in quarters. Shade two quarters: does it match one half?","opts":{"d":2,"shade":1,"compare":4,"compareShade":0}}}});
